import { RayBody, RayLight } from "type";
import { GameScene } from "../GameScene";

const debug = true;

const rayConfig = {
  shadowColor: 0x000000,
  shadowAlpha: 0.5,
};

export class Raycaster {
  constructor(scene: GameScene, light: RayLight, bodies: RayBody[]) {
    const shadows = bodies.map(
      ({ x, y, height, width, radius = 0, type = "circle" }) => {
        if (type === "circle") {
          const shadow = scene.add.circle(
            x,
            y,
            width / 2,
            rayConfig.shadowColor,
            rayConfig.shadowAlpha,
          );
          shadow.setScale(width / shadow.width, height / shadow.height);

          return shadow;
        } else {
          if (radius) {
            const shadow = scene.add.graphics({
              x,
              y,
              fillStyle: {
                color: rayConfig.shadowColor,
                alpha: rayConfig.shadowAlpha,
              },
            });
          } else {
            const shadow = scene.add.rectangle(
              x,
              y,
              width,
              height,
              rayConfig.shadowColor,
              rayConfig.shadowAlpha,
            );

            return shadow;
          }
        }
      },
    );
    if (debug) {
      const lightEdge = scene.add
        .circle(light.x, light.y, light.radius, 0xff0000)
        .setDepth(Infinity)
        .setAlpha(0.075);
    }
  }
}
